// Lista videos montados e pendentes de upload
const fs = require('fs');
const path = require('path');

const outputDir = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\output';
const projetosDir = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\projetos';
const filaPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\fila_upload.json';

let filaUpload = [];
if (fs.existsSync(filaPath)) {
  filaUpload = JSON.parse(fs.readFileSync(filaPath, 'utf-8'));
}

const pendentes = [];

if (fs.existsSync(outputDir)) {
  const arquivos = fs.readdirSync(outputDir).filter(f => f.endsWith('.mp4'));
  for (const arquivo of arquivos) {
    const videoId = arquivo.replace('video_final_', '').replace('.mp4', '');
    const projetoDir = path.join(projetosDir, videoId);
    const resultadoPath = path.join(projetoDir, `resultado_${videoId}.json`);

    if (fs.existsSync(resultadoPath) && !filaUpload.includes(videoId)) {
      const result = JSON.parse(fs.readFileSync(resultadoPath, 'utf-8'));
      pendentes.push({
        json: {
          video_id: videoId,
          caminho_video: path.join(outputDir, arquivo),
          roteiro: result,
        }
      });
    }
  }
}

return pendentes.length > 0 ? pendentes : [{ json: { error: 'Nenhum video pendente de upload' } }];

// Gera metadata SEO para o video
const video = $input.first().json;
const roteiro = video.roteiro;

const titulo = roteiro?.titulo || `Caso INEDITO que ninguém mostrou!`;
const sinopse = roteiro?.sinopse || '';

const userPrompt = `Voce e um especialista em SEO para YouTube brasileiro. Gere descrições e tags otimizadas para vídeos de true crime.

REGRAS:
- Titulo: max 90 chars, com hook emocional, números, palavras de impacto
- Descricao: 250-300 words, inclui hooks, perguntas, CTAs, timestamps, links
- Tags: 15-20 tags, misturando genéricas e específicas de alto volume
