Título original: ${titulo}
Sinopse: ${sinopse}
Segmentos: ${JSON.stringify((roteiro?.segmentos || []).slice(0,5).map(s => s.titulo))}
Thumbnail suggestion: ${roteiro?.thumbnail_suggestion || ''}

Gere o JSON de SEO completo.`;

return [{ json: { userPrompt, video } }];

// Extrai SEO da resposta do Gemini e prepara upload
const fs = require('fs');
const path = require('path');

const inputJson = $input.first().json;
const video = inputJson.video;

// Extrai texto da resposta do Gemini
const seoTexto = inputJson.candidates?.[0]?.content?.parts?.[0]?.text ||
                 JSON.stringify(inputJson);

let seo;
try {
  const match = seoTexto.match(/```json\n?([\s\S]*?)\n?```/) ||
                seoTexto.match(/\{[\s\S]*\}/);
  const jsonStr = match ? match[0].replace(/```json\n?/, '').replace(/\n?```$/, '') : seoTexto;
  seo = JSON.parse(jsonStr);
} catch(e) {
  seo = {
    titulo_optimizado: video.caminho_video.split('\\').pop().replace('.mp4',''),
    descricao_completa: '',
    tags: ['true crime', 'caso', 'brasil']
  };
}

const videoId = video.video_id;
const videoPath = video.caminho_video;

return [{
  json: {
    video_id: videoId,
    video_path: videoPath,
    seo: seo,
    status: 'pronto_para_upload',
    script_upload: `python "C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\scripts\\youtube_service.py" upload "${videoPath}" --title "${(seo.titulo_optimizado || '').replace(/"/g,'\\"')}" --description "${(seo.descricao_completa || '').replace(/"/g,'\\"')}" --tags '${JSON.stringify(seo.tags || []).replace(/"/g,"'"}}`
  }
}];

// Registra upload na fila e atualiza historico
const fs = require('fs');
const path = require('path');

const video = $input.first().json;
const videoId = video.video_id;
const filaPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\fila_upload.json';
const historicoPath = 'C:\\Meu Drive\\IA\\Canal Dark\\canal-dark\\dados\\historico_upload.json';

let fila = [];
if (fs.existsSync(filaPath)) fila = JSON.parse(fs.readFileSync(filaPath, 'utf-8'));
if (!fila.includes(videoId)) fila.push(videoId);
fs.writeFileSync(filaPath, JSON.stringify(fila, null, 2));

let historico = [];
if (fs.existsSync(historicoPath)) historico = JSON.parse(fs.readFileSync(historicoPath, 'utf-8'));
historico.push({
  video_id: videoId,
  data_upload: new Date().toISOString(),
  status: video.status || 'uploaded'
});
fs.writeFileSync(historicoPath, JSON.stringify(historico, null, 2));

return [{ json: { video_id: videoId, status: 'uploaded', data: new Date().toISOString() } }];
